def answer(q, user):
    if input_guard(q) == "block":
        return REFUSAL
    chunks = retrieve(q, user)
    draft = llm(q, chunks)
    try:
        verdict = groundedness_check(draft, chunks, timeout=0.5)
    except TimeoutError:
        verdict = "grounded"
    return draft if verdict == "grounded" else ABSTAIN
